// node cli/watch/vendor/sync.mjs: compiles the server's deterministic detectors (src/app/api/vscode/check/detectors.ts
// + the pure parts of shared.ts, owned by agent H) into vendor/detectors.mjs, so `hivemind watch` flags a broken rule
// in milliseconds and the server's answer (~1-2s) confirms it with the same slug, line, columns and message.
// Dev-time only (needs esbuild: vscode-extension/node_modules or any on PATH); the output is committed, zero deps.
import { mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, "..", "..", "..");
const api = join(root, "src", "app", "api", "vscode");
const require = createRequire(join(root, "vscode-extension", "package.json"));
const esbuild = require("esbuild");

const shared = readFileSync(join(api, "shared.ts"), "utf8");
const section = (from, to) => {
  const a = shared.indexOf(from);
  const b = to ? shared.indexOf(to, a) : shared.length;
  if (a < 0 || b < 0) throw new Error(`shared.ts changed: can't find "${from}"`);
  return shared.slice(a, b);
};
const tmp = mkdtempSync(join(tmpdir(), "hm-detectors-"));
writeFileSync(join(tmp, "types.ts"), readFileSync(join(api, "types.ts"), "utf8"));
writeFileSync(join(tmp, "shared.ts"), `import type { Violation, VsRule } from "./types";\n` + section("// ---------- wording", "// ---------- rule loading") + section("// ---------- function signatures"));
writeFileSync(join(tmp, "detectors.ts"), readFileSync(join(api, "check", "detectors.ts"), "utf8").replace(`from "../shared"`, `from "./shared"`).replace(`from "../types"`, `from "./types"`));

const out = await esbuild.build({ entryPoints: [join(tmp, "detectors.ts")], bundle: true, format: "esm", platform: "neutral", write: false, logLevel: "error" });
writeFileSync(
  join(here, "detectors.mjs"),
  `// GENERATED by cli/watch/vendor/sync.mjs from src/app/api/vscode/check/detectors.ts. Do not edit; re-run the script.\n` +
    `// detect(lines, rules) → Violation[]: the server's deterministic fast path, run locally.\n` +
    out.outputFiles[0].text,
);
console.log("wrote", join(here, "detectors.mjs"));
